SHOW ENGINES;                              -- 查看可用引擎
SHOW VARIABLES LIKE 'transaction_isolation';
SHOW ENGINE INNODB STATUS\G                -- InnoDB 综合诊断（锁、日志、缓冲）
SELECT * FROM information_schema.INNODB_TRX ORDER BY trx_started;   -- 长事务
SELECT * FROM sys.innodb_lock_waits;       -- 当前锁等待（sys schema）
SHOW GLOBAL STATUS LIKE 'Innodb_buffer_pool_read%';

-- 执行计划
EXPLAIN SELECT ...;
EXPLAIN FORMAT=JSON SELECT ...;      -- 含成本明细（8.0 推荐看这个）
EXPLAIN ANALYZE SELECT ...;          -- 8.0.18+：真实执行并输出每步耗时

-- 索引与统计
SHOW INDEX FROM t;
ANALYZE TABLE t;

-- 现场观测
SELECT * FROM sys.statements_with_full_table_scans LIMIT 10;   -- sys schema 视角
SHOW GLOBAL STATUS LIKE 'Select_scan';                          -- 全表扫描累计次数

-- 原语句（慢日志 top1，单次 2.4s）
SELECT order_no, amount FROM orders
WHERE user_id = 9527 AND status = 'PAID'
ORDER BY create_time DESC LIMIT 20;

EXPLAIN ...;
-- type=ALL, rows=880万, Extra=Using where; Using filesort  → 全表扫描+排序

-- 优化：按"等值列在前、排序列在后"设计联合索引
ALTER TABLE orders ADD INDEX idx_user_status_time (user_id, status, create_time);
EXPLAIN ...;
-- type=ref, rows=36, Extra=Backward index scan 或 Using where（无需 filesort）

CREATE USER 'app_rw'@'10.0.%' IDENTIFIED BY 'Ap#2026Str0ng';
ALTER USER 'app_rw'@'10.0.%' PASSWORD EXPIRE INTERVAL 90 DAY;
ALTER USER 'app_rw'@'10.0.%' FAILED_LOGIN_ATTEMPTS 5 PASSWORD_LOCK_TIME 1;

GRANT SELECT, INSERT, UPDATE, DELETE ON appdb.* TO 'app_rw'@'10.0.%';
GRANT PROCESS, REPLICATION CLIENT, SELECT ON performance_schema.* TO 'moni'@'127.0.0.1';

SHOW GRANTS FOR 'app_rw'@'10.0.%';
REVOKE DELETE ON appdb.* FROM 'app_rw'@'10.0.%';
DROP USER 'legacy_app'@'%';

INSTALL COMPONENT 'file://component_validate_password';
SHOW VARIABLES LIKE 'validate_password%';

-- 1) 全量账号清单与主机范围
SELECT user, host, account_locked, password_expired,
       plugin, IF(host='%' , 'RISK-WIDE-HOST','') AS flag
FROM mysql.user ORDER BY user, host;

-- 2) 每个账号的实际权限
SELECT * FROM information_schema.user_privileges;
SELECT * FROM information_schema.schema_privileges;

-- 3) 找出风险项
--    a) host='%' 的账号        → 收敛到业务网段
--    b) 持有全局 ALL PRIVILEGES 的账号 → 逐个降级
--    c) 只读需求却给了 DML      → REVOKE 掉多余权限
-- 4) 处置示例
REVOKE ALL PRIVILEGES ON *.* FROM 'report'@'%';
GRANT SELECT ON appdb.* TO 'report'@'10.0.%';
ALTER USER 'report'@'%' -> '10.0.%'   -- 8.0 不支持直接改 host，
                                      -- 正确做法：RENAME USER 'report'@'%' TO 'report'@'10.0.%';

CREATE USER 'bakuser'@'localhost' IDENTIFIED BY 'Bak#2026';
GRANT BACKUP_ADMIN, PROCESS, RELOAD, LOCK TABLES, REPLICATION CLIENT ON *.* TO 'bakuser'@'localhost';
GRANT SELECT ON performance_schema.log_status TO 'bakuser'@'localhost';

-- 主库
INSTALL PLUGIN rpl_semi_sync_source SONAME 'semisync_source.so';
SET GLOBAL rpl_semi_sync_source_enabled=1;
SET GLOBAL rpl_semi_sync_source_timeout=3000;        -- 3 秒无 ack 降级异步
SET GLOBAL rpl_semi_sync_source_wait_for_slave_count=1;

-- 从库
INSTALL PLUGIN rpl_semi_sync_replica SONAME 'semisync_replica.so';
SET GLOBAL rpl_semi_sync_replica_enabled=1;

-- 验证
SHOW STATUS LIKE 'Rpl_semi_sync_source_status';
SHOW STATUS LIKE 'Rpl_semi_sync_source_clients';

-- 首节点引导 / 后续节点加入
SET GLOBAL group_replication_bootstrap_group=ON;
START GROUP_REPLICATION;
SET GLOBAL group_replication_bootstrap_group=OFF;
-- 第二/三节点直接 START GROUP_REPLICATION;

SELECT * FROM performance_schema.replication_group_members;    -- 成员状态
SELECT * FROM performance_schema.replication_group_member_stats;

-- mysql 客户端连 ProxySQL 管理接口（6032）
mysql -u admin -padmin -h 127.0.0.1 -P 6032

-- 1) 定义后端组：HG10=写（主）、HG20=读（从）
INSERT INTO mysql_servers (hostgroup_id, hostname, port) VALUES
 (10, '10.0.0.11', 3306), (20, '10.0.0.12', 3306), (20, '10.0.0.13', 3306);

-- 2) 按 read_only 自动归位主从
INSERT INTO mysql_replication_hostgroups (writer_hostgroup, reader_hostgroup, check_type)
VALUES (10, 20, 'read_only');

-- 3) 读写分流规则：默认写走 HG10，SELECT 走 HG20
INSERT INTO mysql_query_rules (rule_id, active, match_pattern, destination_hostgroup, apply)
VALUES (1, 1, '^SELECT .* FOR UPDATE', 10, 1),    -- FOR UPDATE 回主库
       (2, 1, '^SELECT', 20, 1);

-- 4) 加载生效
LOAD MYSQL SERVERS TO RUNTIME; LOAD MYSQL QUERY RULES TO RUNTIME;
SAVE MYSQL SERVERS TO DISK;    SAVE MYSQL QUERY RULES TO DISK;

-- GTID 模式：跳过一个事务（构造空事务占位）
STOP REPLICA SQL_THREAD;
SET GTID_NEXT='3E11FA47-...:42';   -- 要跳过的 GTID
BEGIN; COMMIT;                     -- 空事务，让从库标记"该 GTID 已执行"
SET GTID_NEXT='AUTOMATIC';
START REPLICA SQL_THREAD;

-- 位点模式：跳过 N 个事件（不推荐超过 1）
STOP REPLICA SQL_THREAD;
SET GLOBAL sql_replica_skip_counter=1;
START REPLICA SQL_THREAD;

-- ① 停应用写入（维护窗口），等待原主从库全部追平
SHOW REPLICA STATUS\G                    -- 原 A/B 对旧主延迟应为 0

-- ② 原主降级为只读（防新写入）
SET GLOBAL super_read_only=1;

-- ③ A（候选新主）上停复制，确认执行位点
STOP REPLICA;
SELECT @@global.gtid_executed;

-- ④ A 解除只读，其他从库 B 改指向新主
SET GLOBAL super_read_only=0;
-- B 上执行：
CHANGE REPLICATION SOURCE TO SOURCE_HOST='10.0.0.12', SOURCE_AUTO_POSITION=1;
START REPLICA; SHOW REPLICA STATUS\G     -- 双 Yes 且延迟 0

-- ⑤ 原主也改指向 A（保持拓扑），应用切流量 → 验证业务 → 解除维护

-- 采集账号
CREATE USER 'exporter'@'127.0.0.1' IDENTIFIED BY 'Exp#2026Str0ng';
GRANT PROCESS, REPLICATION CLIENT ON *.* TO 'exporter'@'127.0.0.1';
GRANT SELECT ON performance_schema.* TO 'exporter'@'127.0.0.1';

-- 现场快速体检（人肉巡检四连）
SHOW GLOBAL STATUS LIKE 'Threads_connected';
SHOW GLOBAL STATUS LIKE 'Slow_queries';
SHOW GLOBAL STATUS LIKE 'Innodb_row_lock_waits';
SHOW REPLICA STATUS\G

// 伪代码：互斥锁重建缓存
String val = redis.get(key);
if (val == null) {                                  // miss
    if (redis.setnx("lock:" + key, uuid, 5s)) {     // 抢锁成功者回源
        try {
            val = db.query(key);
            redis.set(key, val, ttl + jitter());    // TTL 加抖动，顺带防雪崩
        } finally {
            releaseLock("lock:" + key, uuid);       // 只释放自己的锁
        }
    } else {
        sleep(50); return redis.get(key);           // 其余请求短暂重试
    }
}

